import fs from'node:fs';import zlib from'node:zlib';import path from'node:path';import assert from'node:assert/strict';import crypto from'node:crypto';import{load,ROOT,DEFAULT_STATE}from'./fixtures.mjs';
import{UnifiedModel,validateProfile}from'./candidate/kaopu-unified-human-workbench/src/UnifiedModel.js';import{NeckSurface,loadNeckSurface}from'./candidate/kaopu-unified-human-workbench/src/NeckSurface.js';import{R01Assets}from'./candidate/kaopu-unified-human-workbench/src/R01Assets.js';
const{m:baseline,anny,gnm,c}=load(),root=path.join(ROOT,'candidate/kaopu-unified-human-workbench'),fp=JSON.parse(fs.readFileSync(path.join(root,'assets/adapter-fingerprint.json'))),meta=JSON.parse(fs.readFileSync(path.join(root,'assets/neck-surface.json'))),b=zlib.gunzipSync(fs.readFileSync(path.join(root,'assets/neck-surface.bin.gz'))),surface=new NeckSurface(meta,b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength)),m=new UnifiedModel(anny,gnm,c,baseline.mhr,fp,surface),cases=JSON.parse(fs.readFileSync(path.join(ROOT,'research/neck-runtime-probe-report.json'))).caseRows,positions=m.positions,faces=m.faces,report=[];
for(const row of cases){const old=baseline.compute(row.state).slice(),v=m.compute(row.state);const digest=crypto.createHash('sha256').update(v).digest('hex');assert.equal(digest,row.positionsSHA256);assert.equal(v,positions);assert.equal(m.faces,faces);const mask=new Set(surface.indices);for(let i=0;i<m.vertexCount;i++)if(!mask.has(i))for(let k=0;k<3;k++)assert.equal(v[i*3+k],old[i*3+k]);const profile={...structuredClone(row.state),topologySha256:c.topologySha256,adapterFingerprint:fp.id};assert.deepEqual(m.compute(validateProfile(profile,m)),v);const legacy={...profile,adapterFingerprint:baseline.adapterFingerprint},migrated=validateProfile(legacy,m);assert.equal(migrated.migrationFrom,baseline.adapterFingerprint);assert(!Object.keys(migrated).includes('migrationFrom'));assert.deepEqual(m.compute(migrated),v);assert.throws(()=>validateProfile({...legacy,adapterFingerprint:'f'.repeat(64)},m));report.push({case:row.name,byteExact:true,profileRoundtrip:true,explicitLegacyParameterMigration:true});}
const baselineURL='https://test.invalid/kaopu-unified-human-workbench/';let calls=[];const read=async(url,{signal}={})=>{assert.equal(this,undefined);const u=new URL(url);calls.push(u.pathname);if(signal?.aborted)throw new DOMException('Aborted','AbortError');let p;if(u.hostname==='raw.githubusercontent.com')p=path.join(ROOT,'baseline/kaopu-face-workbench/assets/gnm_head_web.bin');else if(u.pathname.startsWith('/kaopu-unified-human-workbench/'))p=path.join(root,u.pathname.slice('/kaopu-unified-human-workbench/'.length));else p=path.join(ROOT,'baseline',u.pathname.slice(1));return new Response(fs.readFileSync(p));};const assets=await new R01Assets(baselineURL,read).load('https://raw.githubusercontent.com/xrblocks/assets-gnm/134feb02b11fa642a43ff5e7e880246255a74e86/gnm_head_web.bin');assert(assets.neckSurface);const parsed=new UnifiedModel(anny,gnm,c,assets.mhr,assets.fingerprint,assets.neckSurface);assert.deepEqual(parsed.compute(DEFAULT_STATE()),m.compute(DEFAULT_STATE()));
const output={passed:true,cases:report,adapterFingerprint:fp.id,topologySHA256:c.topologySha256,originalFaceAndExteriorExact:true,unchangedPositionAndIndexBuffers:true,actualHashPinnedRuntimeLoader:true,hashCheckedNeckMetadataAndCompressedAndRaw:true,requests:calls.length};fs.writeFileSync(path.join(ROOT,'research/integration-report.json'),JSON.stringify(output,null,2));console.log({passed:true,cases:report.length,fingerprint:fp.id,requests:calls.length});
